var b=WebApplication.CreateBuilder(args);b.Services.AddEndpointsApiExplorer();b.Services.AddSwaggerGen();var app=b.Build();app.UseSwagger();app.UseSwaggerUI();var state=new TrainingState();app.MapGet("/health",()=>Results.Ok(new{status="healthy",service="DeviceSimulator"}));
app.MapGet("/api/devices/{serial}/status",async(string serial)=>{var delay=state.Mode=="Intermittent"?Random.Shared.Next(250,1001):state.LatencyMs;if(delay>0)await Task.Delay(delay);if(state.Mode=="Offline"||(state.RandomFailures&&Random.Shared.NextDouble()<.12))return Results.StatusCode(503);var battery=serial switch{"NP-1001"=>87,"NP-1002"=>42,"NP-1003"=>71,"NP-1004"=>9,"NP-1005"=>100,"NP-1006"=>55,"NP-1007"=>18,_=>4};var connected=serial is "NP-1001" or "NP-1002" or "NP-1004" or "NP-1005" or "NP-1007";return state.ContractVersion=="V2"?Results.Ok(new{id=serial,status=connected?"ONLINE":"OFFLINE",batteryPercent=battery}):Results.Ok(new{deviceId=serial,connected,battery});});
app.MapGet("/api/devices/{serial}/telemetry",(string serial)=>Results.Ok(new{deviceId=serial,timestamp=DateTime.UtcNow,signal=Random.Shared.Next(40,96),quality=Math.Round(Random.Shared.NextDouble(),2),batteryPercentage=Random.Shared.Next(10,100)}));app.MapGet("/api/training/config",()=>state);app.MapPost("/api/training/config",(TrainingUpdate u)=>{state.Apply(u);return Results.Ok(state);});app.MapPost("/api/training/scenarios/{name}",(string name)=>{state.Preset(name);return Results.Ok(state);});app.Run();
class TrainingState { public string Mode{get;set;}="Healthy";public int LatencyMs{get;set;}=0;public bool RandomFailures{get;set;}=false;public string ContractVersion{get;set;}="V1";public string TelemetryMode{get;set;}="Normal";public bool StaleStatus{get;set;}=false;public void Apply(TrainingUpdate u){Mode=u.Mode;LatencyMs=u.LatencyMs;RandomFailures=u.RandomFailures;ContractVersion=u.ContractVersion;TelemetryMode=u.TelemetryMode;StaleStatus=u.StaleStatus;}public void Preset(string n){Mode="Healthy";LatencyMs=0;RandomFailures=false;ContractVersion="V1";TelemetryMode="Normal";StaleStatus=false;if(n=="Slow Device Network"){Mode="Slow";LatencyMs=3000;}else if(n=="Unreliable Device"){Mode="Intermittent";RandomFailures=true;}else if(n=="Contract Breaking Change")ContractVersion="V2";else if(n=="Performance Stress")TelemetryMode="High Volume";else if(n=="Exploratory Testing"){Mode="Intermittent";LatencyMs=250;StaleStatus=true;}}}
record TrainingUpdate(string Mode,int LatencyMs,bool RandomFailures,string ContractVersion,string TelemetryMode,bool StaleStatus);
